        self.amount = float(amount)

    def __add__(self, other):
        return Money(self.amount + other.amount)

    def __mul__(self, qty):
        return Money(self.amount * qty)

    def __eq__(self, other):
        # Compare with small epsilon to handle floating point precision
        return abs(self.amount - other.amount) < 1e-9

    def __repr__(self):
        return f"Money({self.amount:.2f})"

    def cents(self):
        # Use round to handle floating point precision properly
        return round(self.amount * 100)

